body.script:
//
(function () {
  var checkoutEl = document.getElementById('ac-saas-rzp-checkout');
  var btn = document.getElementById('acSaasPayBtn');
  var err = document.getElementById('acSaasPayErr');
  var meta = document.getElementById('acSaasRzpMeta');
  var verifyUrl = (meta && meta.getAttribute('data-verify-url')) || '';
  var autoOpen = meta && meta.getAttribute('data-auto-open') === '1';

  function showErr(msg) {
    if (!err) return;
    err.style.display = 'block';
    err.textContent = msg || 'Payment failed.';
  }

  function setBusy(busy) {
    if (!btn) return;
    btn.disabled = !!busy;
    btn.style.opacity = busy ? '0.75' : '';
  }

  function openCheckout() {
    var checkout = {};
    try {
      checkout = JSON.parse((checkoutEl && checkoutEl.textContent) || '{}');
    } catch (e) {
      showErr('Invalid checkout data.');
      return;
    }
    if (!window.Razorpay) {
      showErr('Razorpay could not load. Check your network and try again.');
      return;
    }
    var options = {
      key: checkout.key_id,
      amount: checkout.amount,
      currency: checkout.currency,
      name: checkout.name || 'AuctionChamp',
      description: checkout.description || '',
      order_id: checkout.order_id,
      prefill: checkout.prefill || {},
      theme: { color: '#0d1e3a' },
      handler: function (response) {
        setBusy(true);
        fetch(verifyUrl, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Requested-With': 'XMLHttpRequest'
          },
          credentials: 'same-origin',
          body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_order_id: response.razorpay_order_id,
              razorpay_signature: response.razorpay_signature
            },
            id: Date.now()
          })
        }).then(function (r) { return r.json(); })
          .then(function (payload) {
            var result = (payload && payload.result) || payload || {};
            if (result.ok) {
              window.location.href = result.redirect_url || (window.location.pathname + '?done=1');
            } else {
              setBusy(false);
              showErr(result.error || 'Verification failed.');
            }
          })
          .catch(function () {
            setBusy(false);
            showErr('Could not verify payment. Please contact support with your payment id.');
          });
      },
      modal: {
        ondismiss: function () {
          setBusy(false);
          showErr('Payment cancelled. You can try again.');
        }
      }
    };
    var rzp = new window.Razorpay(options);
    rzp.open();
  }

  if (btn) {
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      openCheckout();
    });
  }
  if (autoOpen) {
    setTimeout(openCheckout, 400);
  }
})();
//
